refentry.refsect1:
&reftitle.description;
intfalsefileperms stringfilename
Gibt die Zugriffsrechte für die übergebene Datei zurück.

  &reftitle.examples;



    Zeige die Zugriffsrechte als Oktalwert an


<?php
echo substr(sprintf('%o', fileperms('/tmp')), -4);
echo substr(sprintf('%o', fileperms('/etc/passwd')), -4);
?>


    &example.outputs;


1777
0644




    Zeige die kompletten Zugriffsrechte an


<?php
$perms = fileperms('/etc/passwd');

switch ($perms & 0xF000) {
    case 0x1000: $info = 'p'; break; // FIFO pipe
    case 0x2000: $info = 'c'; break; // Character special
    case 0x4000: $info = 'd'; break; // Verzeichnis
    case 0x6000: $info = 'b'; break; // Block special
    case 0x8000: $info = '-'; break; // Regulär
    case 0xA000: $info = 'l'; break; // Symbolischer Link (verfügbar bei verwendung der funktion lstat)
    case 0xC000: $info = 's'; break; // Socket

    // unbekannt
    default: $info = 'u';
}

// Besitzer
$setuid = $perms & 0x0800;
$info .= (($perms & 0x0100) ? 'r' : '-');
$info .= (($perms & 0x0080) ? 'w' : '-');
$info .= (($perms & 0x0040) ? ($setuid ? 's' : 'x') : ($setuid ? 'S' : '-'));

// Gruppe
$setgid = $perms & 0x0400;
$info .= (($perms & 0x0020) ? 'r' : '-');
$info .= (($perms & 0x0010) ? 'w' : '-');
$info .= (($perms & 0x0008) ? ($setgid ? 's' : 'x') : ($setgid ? 'S' : '-'));

// Andere
$sticky = $perms & 0x0200;
$info .= (($perms & 0x0004) ? 'r' : '-');
$info .= (($perms & 0x0002) ? 'w' : '-');
$info .= (($perms & 0x0001) ? ($sticky ? 't' : 'x') : ($sticky ? 'T' : '-'));

echo $info;
?>


    &example.outputs;


